14	    name = "sw-launch",
15	    version,
16	    about = "Host-side reproducible scenario launcher for COR24 emulator workflows",
17	    long_about = None,
18	)]
19	pub struct Cli {
20	    #[command(subcommand)]
21	    pub command: Commands,
22	}
23	
24	/// Top-level subcommands.
25	#[derive(Debug, Subcommand)]
26	pub enum Commands {
27	    /// Build (with cache) and execute a scenario; check expectations.
28	    Run {
29	        /// Name of the scenario in `sw-launch.toml`.
30	        scenario: String,
31	    },
32	    /// Build all layers of a scenario; do not execute.
33	    Build {
34	        /// Name of the scenario in `sw-launch.toml`.
35	        scenario: String,
36	    },
37	    /// Validate config + lockfile for a scenario; no tools spawned.
38	    Check {
39	        /// Name of the scenario in `sw-launch.toml`.
40	        scenario: String,
41	    },
42	    /// Print the layer DAG for a scenario.
43	    Graph {
44	        /// Name of the scenario in `sw-launch.toml`.
45	        scenario: String,
46	    },
47	    /// Inspect or clean the build cache.
48	    Cache {
49	        #[command(subcommand)]
50	        action: CacheAction,
51	    },
52	    /// Resolve and inspect vendored dependencies.
53	    Vendor {
54	        #[command(subcommand)]
55	        action: VendorAction,
56	    },
57	    /// Verify that host tools (cor24-run, pa24r, ...) are reachable.
58	    Doctor,
59	}
60	
61	/// `sw-launch cache <action>` subcommands.
62	#[derive(Debug, Subcommand)]
63	pub enum CacheAction {
64	    /// List cached artifacts.
65	    List,
