    pub const CLI: ErrorCode = ErrorCode(91);
    /// `E0092`: I/O error reading or writing a file.
    pub const IO: ErrorCode = ErrorCode(92);
}

impl fmt::Display for ErrorCode {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "E{:04}", self.0)
    }
}

